export default async function install(app) {
  const [FeatureLayer,GraphicsLayer,Graphic,CIMSymbol,webMercatorUtils]=await Promise.all([app.import("esri/layers/FeatureLayer"),app.import("esri/layers/GraphicsLayer"),app.import("esri/Graphic"),app.import("esri/symbols/CIMSymbol"),app.import("esri/geometry/support/webMercatorUtils")]);
  const modeMount=app.getMount("capacity-mode-dialog"),typeMount=app.getMount("substation-type-dialog"),levelMount=app.getMount("voltage-level-dialog");
  const source=new FeatureLayer({url:app.config.serviceUrl,outFields:["*"]});await source.load();
  const graphicsLayer=new GraphicsLayer({id:"live-capacity-graphics",title:"NIE Networks Live Capacity",listMode:"show",popupEnabled:true});app.map.add(graphicsLayer);app.view.popupEnabled=true;
  const state={mode:"generation",types:new Set(["PRI","CSP","BSP"]),levels:new Set(["pri-11","pri-66","bsp-110"])};
  const colors={Green:[46,133,64,255],Amber:[245,166,35,255],Red:[214,69,69,255],Blue:[56,108,176,255],default:[112,112,112,255]};
  const modes={demand:{label:"Demand",prefix:"Demand_Headroom_RAG",headroom:"Demand_Headroom"},generation:{label:"Generation",prefix:"Generation_Headroom_RAG",headroom:"Generation_Headroom"},fault:{label:"Fault level",prefix:"Fault_Headroom_RAG",headroom:"Fault_Headroom"}};
  const summaries={};
  const makeDialog=(mount,title,summary)=>{const wrap=document.createElement("div"),button=document.createElement("calcite-button"),text=document.createElement("span"),dialog=document.createElement("calcite-dialog"),body=document.createElement("div"),close=document.createElement("calcite-button");Object.assign(wrap.style,{display:"flex",alignItems:"center",gap:"8px"});button.setAttribute("appearance","outline");button.setAttribute("scale","s");button.textContent=`Choose ${title.toLowerCase()}`;Object.assign(text.style,{fontSize:"0.8rem",color:"var(--app-text-muted)",whiteSpace:"nowrap"});text.textContent=summary;summaries[title]=text;dialog.setAttribute("heading",title);dialog.setAttribute("modal","true");dialog.setAttribute("width-scale","s");Object.assign(body.style,{display:"grid",gap:"10px",padding:"4px"});dialog.append(body);close.setAttribute("slot","footer-end");close.textContent="Done";dialog.append(close);const open=()=>dialog.open=true,shut=()=>dialog.open=false;button.addEventListener("click",open);close.addEventListener("click",shut);app.onCleanup(()=>{button.removeEventListener("click",open);close.removeEventListener("click",shut)});wrap.append(button,text,dialog);mount.replaceChildren(wrap);return body};
  const modeBody=makeDialog(modeMount,"Capacity mode","Generation"),typeBody=makeDialog(typeMount,"Substation type","All 3 selected"),levelBody=makeDialog(levelMount,"Voltage level","All 3 selected");
  const refresh=()=>{summaries["Capacity mode"].textContent=modes[state.mode].label;summaries["Substation type"].textContent=state.types.size===3?"All 3 selected":`${state.types.size} selected`;summaries["Voltage level"].textContent=state.levels.size===3?"All 3 selected":`${state.levels.size} selected`};
  const addRadio=(body,label,value)=>{const row=document.createElement("label"),input=document.createElement("input");Object.assign(row.style,{display:"flex",alignItems:"center",gap:"8px"});input.type="radio";input.name="capacity-mode";input.value=value;input.checked=state.mode===value;const change=()=>{state.mode=value;refresh();update()};input.addEventListener("change",change);app.onCleanup(()=>input.removeEventListener("change",change));row.append(input,document.createTextNode(label));body.append(row)};
  const addCheck=(body,label,value,set)=>{const row=document.createElement("label"),input=document.createElement("input");Object.assign(row.style,{display:"flex",alignItems:"center",gap:"8px"});input.type="checkbox";input.value=value;input.checked=set.has(value);const change=()=>{input.checked?set.add(value):set.delete(value);refresh();update()};input.addEventListener("change",change);app.onCleanup(()=>input.removeEventListener("change",change));row.append(input,document.createTextNode(label));body.append(row)};
  addRadio(modeBody,"Demand","demand");addRadio(modeBody,"Generation","generation");addRadio(modeBody,"Fault level","fault");addCheck(typeBody,"Primary","PRI",state.types);addCheck(typeBody,"Dual primary","CSP",state.types);addCheck(typeBody,"Bulk supply point","BSP",state.types);addCheck(levelBody,"33/11 kV","pri-11",state.levels);addCheck(levelBody,"33/6.6 kV","pri-66",state.levels);addCheck(levelBody,"110/33 kV","bsp-110",state.levels);
  const polygon=points=>({type:"esriGeometryPolygon",rings:[points]});
  const cubic=(p0,p1,p2,p3,steps=14)=>{const out=[];for(let i=1;i<=steps;i++){const t=i/steps,u=1-t;out.push([u*u*u*p0[0]+3*u*u*t*p1[0]+3*u*t*t*p2[0]+t*t*t*p3[0],u*u*u*p0[1]+3*u*u*t*p1[1]+3*u*t*t*p2[1]+t*t*t*p3[1]])}return out};
  const tip=[0,-14],left=[-10,3],top=[0,13],right=[10,3],ll=cubic(tip,[-2,-10],[-10,-4],left),lu=cubic(left,[-10,9],[-5,13],top),ru=cubic(top,[5,13],[10,9],right),rl=cubic(right,[10,-4],[2,-10],tip),full=polygon([tip,...ll,...lu,...ru,...rl]),leftHalf=polygon([tip,...ll,...lu,tip]),rightHalf=polygon([tip,top,...ru,...rl]);
  const fill=color=>({type:"CIMPolygonSymbol",symbolLayers:[{type:"CIMSolidFill",enable:true,color},{type:"CIMSolidStroke",enable:true,color:[255,255,255,255],width:1}]}),shape=(geometry,color)=>({type:"CIMMarkerGraphic",geometry,symbol:fill(color)}),label=value=>({type:"CIMMarkerGraphic",textString:value,geometry:{type:"esriGeometryPoint",x:0,y:3},symbol:{type:"CIMTextSymbol",fontFamilyName:"Arial",fontStyleName:"Bold",height:7,horizontalAlignment:"Center",verticalAlignment:"Center",symbol:{type:"CIMPolygonSymbol",symbolLayers:[{type:"CIMSolidFill",enable:true,color:[255,255,255,255]}]}}});
  const pin=(a,b,text,split)=>new CIMSymbol({data:{type:"CIMSymbolReference",symbol:{type:"CIMPointSymbol",symbolLayers:[{type:"CIMVectorMarker",enable:true,size:29,frame:{xmin:-10,ymin:-14,xmax:10,ymax:13},anchorPoint:{x:0,y:-0.5},anchorPointUnits:"Relative",markerGraphics:split?[shape(leftHalf,a),shape(rightHalf,b),label(text)]:[shape(full,a),label(text)]}]}}});
  const color=v=>colors[v]||colors.default,baseName=n=>String(n||"").replace(/\s*\[[^\]]+\]\s*$/,"").trim(),typeLabel=t=>t==="PRI"?"Primary":t==="CSP"?"Dual primary":"Bulk supply point";
  const levelSelected=a=>(state.levels.has("pri-11")&&a.Voltage_Domain_PRI==="33/11kV")||(state.levels.has("pri-66")&&a.Voltage_Domain_PRI==="33/6.6kV")||(state.levels.has("bsp-110")&&a.Voltage_Domain_BSP==="110/33kV");
  const singlePopup={title:"{name}",content:[{type:"fields",fieldInfos:[{fieldName:"typeLabel",label:"Substation type"},{fieldName:"primaryVoltage",label:"Primary voltage"},{fieldName:"bulkVoltage",label:"Bulk voltage"},{fieldName:"mode",label:"Capacity mode"},{fieldName:"primaryStatus",label:"Primary RAG status"},{fieldName:"bulkStatus",label:"Bulk RAG status"},{fieldName:"primaryHeadroom",label:"Primary headroom"},{fieldName:"bulkHeadroom",label:"Bulk headroom"}]}]};
  const pairPopup={title:"{name}",content:[{type:"fields",fieldInfos:[{fieldName:"typeLabel",label:"Substation type"},{fieldName:"mode",label:"Capacity mode"},{fieldName:"leftName",label:"Substation 1"},{fieldName:"leftVoltage",label:"Substation 1 voltage"},{fieldName:"leftStatus",label:"Substation 1 RAG status"},{fieldName:"leftHeadroom",label:"Substation 1 headroom"},{fieldName:"rightName",label:"Substation 2"},{fieldName:"rightVoltage",label:"Substation 2 voltage"},{fieldName:"rightStatus",label:"Substation 2 RAG status"},{fieldName:"rightHeadroom",label:"Substation 2 headroom"},{fieldName:"bulkVoltage",label:"Shared bulk voltage"}]}]};
  let request=0;
  const update=async()=>{const mine=++request,result=await source.queryFeatures({where:"1=1",outFields:["*"],returnGeometry:true});if(mine!==request)return;const selected=modes[state.mode],pairs=new Map(),ordinary=[];
    for(const feature of result.features){const a=feature.attributes;if(a.Type==="PRI"&&(a.ESRI_split_pin==="L"||a.ESRI_split_pin==="R")){const key=baseName(a.Name);if(!pairs.has(key))pairs.set(key,{});pairs.get(key)[a.ESRI_split_pin]=feature}else ordinary.push(feature)}
    const graphics=[];
    for(const feature of ordinary){const a=feature.attributes;if(!state.types.has(a.Type)||!levelSelected(a))continue;const pri=color(a[`${selected.prefix}_PRI`]),bsp=color(a[`${selected.prefix}_BSP`]),split=a.Type==="CSP"&&a.ESRI_split_pin==="S";graphics.push(new Graphic({geometry:webMercatorUtils.geographicToWebMercator(feature.geometry),attributes:{name:a.Name,typeLabel:typeLabel(a.Type),primaryVoltage:a.Voltage_Domain_PRI,bulkVoltage:a.Voltage_Domain_BSP,mode:selected.label,primaryStatus:a[`${selected.prefix}_PRI`],bulkStatus:a[`${selected.prefix}_BSP`],primaryHeadroom:a[`${selected.headroom}_PRI`],bulkHeadroom:a[`${selected.headroom}_BSP`]},popupTemplate:singlePopup,symbol:pin(a.Type==="BSP"?bsp:pri,bsp,a.Type==="PRI"?"P":a.Type==="CSP"?"PP":"BP",split)}))}
    let mergedPairs=0;
    for(const [name,pair] of pairs){if(!pair.L||!pair.R){for(const feature of [pair.L,pair.R].filter(Boolean))ordinary.push(feature);continue}const la=pair.L.attributes,ra=pair.R.attributes;if(!state.types.has("CSP")||!(levelSelected(la)||levelSelected(ra)))continue;graphics.push(new Graphic({geometry:webMercatorUtils.geographicToWebMercator(pair.L.geometry),attributes:{name,typeLabel:"Dual primary",mode:selected.label,leftName:la.Name,leftVoltage:la.Voltage_Domain_PRI,leftStatus:la[`${selected.prefix}_PRI`],leftHeadroom:la[`${selected.headroom}_PRI`],rightName:ra.Name,rightVoltage:ra.Voltage_Domain_PRI,rightStatus:ra[`${selected.prefix}_PRI`],rightHeadroom:ra[`${selected.headroom}_PRI`],bulkVoltage:la.Voltage_Domain_BSP||ra.Voltage_Domain_BSP},popupTemplate:pairPopup,symbol:pin(color(la[`${selected.prefix}_PRI`]),color(ra[`${selected.prefix}_PRI`]),"PP",true)}));mergedPairs++}
    graphicsLayer.removeAll();graphicsLayer.addMany(graphics);app.setStatus(`${graphics.length} live capacity sites — ${selected.label} (${mergedPairs} paired dual-primary sites)`)};
  refresh();await update();
  app.onCleanup(()=>{graphicsLayer.removeAll();app.map.remove(graphicsLayer);source.destroy();modeMount.replaceChildren();typeMount.replaceChildren();levelMount.replaceChildren()});
  return {graphics:graphicsLayer.graphics.length,mode:state.mode,pairedDualPrimary:true,popupEnabled:true};
}